def hold_grip(arm, grip, count):
    obs = get_observation()
    s = obs['state']
    action = {'left_ee_pose': s['left_ee_pose'], 'right_ee_pose': s['right_ee_pose'], 'left_ee_joint_state': s['left_ee_joint_state'], 'right_ee_joint_state': s['right_ee_joint_state']}
